import 'dart:io';import 'package:flutter/material.dart';import '../../models/media_post.dart';import '../../services/demo_store.dart';class MediaDetailScreen extends StatelessWidget{final MediaPost media;const MediaDetailScreen({super.key,required this.media});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Post')),body:ListView(children:[if(media.localPath!=null)Image.file(File(media.localPath!),fit:BoxFit.contain),ListTile(title:Text(media.displayName??'User'),subtitle:Text('❤️ ${media.likeCount}  💬 ${media.commentCount}'),trailing:IconButton(onPressed:()=>DemoStore.instance.toggleLike(media),icon:Icon(media.liked?Icons.favorite:Icons.favorite_border))),const Padding(padding:EdgeInsets.all(20),child:Text('Comments and Creator Chat are available in the production Supabase build.'))]));}
